// HTMLToMarkdown.swift
// ThoughtVault
// com.buildmind.ThoughtVault
//
// Lightweight HTML→Markdown conversion shared by the file exports and the
// Obsidian integration. Regex-based: notule HTML is generated by us and uses a
// small, known tag set, but the styled profiles wrap it in `<style>` + semantic
// `<div>`s (kicker, sections, decision callouts, badge chips), so those are
// flattened to clean Markdown here.

import Foundation

private func regex(_ pattern: String, _ replacement: String, _ s: String) -> String {
    s.replacingOccurrences(of: pattern, with: replacement, options: .regularExpression)
}

/// Converts notule HTML to Markdown.
func htmlToMarkdown(_ html: String) -> String {
    var md = html

    // 1. Drop non-content blocks — otherwise the CSS in <style> leaks as text.
    md = regex("(?is)<style[^>]*>.*?</style>", "", md)
    md = regex("(?is)<script[^>]*>.*?</script>", "", md)
    md = regex("(?is)<head[^>]*>.*?</head>", "", md)
    md = regex("(?s)<!--.*?-->", "", md)
    md = regex("(?is)<div[^>]*class=\"[^\"]*kicker[^\"]*\"[^>]*>.*?</div>", "", md)  // drop the "Vergaderverslag" label

    // 2. Badge/meta chips (e.g. "Installateur", "Vóór woensdag") → inline so they
    //    stay on the same line as their list item. Other </span> become a space so
    //    adjacent inline spans (e.g. the Datum/Type meta) don't glue together.
    md = regex("(?is)<span[^>]*class=\"[^\"]*badge[^\"]*\"[^>]*>(.*?)</span>", " — $1", md)
    md = regex("(?i)</span>", " ", md)

    // 3. Headings.
    md = regex("(?is)<h1[^>]*>(.*?)</h1>", "\n# $1\n", md)
    md = regex("(?is)<h2[^>]*>(.*?)</h2>", "\n## $1\n", md)
    md = regex("(?is)<h3[^>]*>(.*?)</h3>", "\n### $1\n", md)
    md = regex("(?is)<h4[^>]*>(.*?)</h4>", "\n#### $1\n", md)

    // 4. Inline emphasis.
    md = regex("(?is)<(strong|b)[^>]*>(.*?)</\\1>", "**$2**", md)
    md = regex("(?is)<(em|i)[^>]*>(.*?)</\\1>", "*$2*", md)

    // 5. List items, line breaks, paragraphs, quotes.
    md = regex("(?is)<li[^>]*>(.*?)</li>", "\n- $1", md)
    md = regex("(?i)<br\\s*/?>", "\n", md)
    md = regex("(?is)<p[^>]*>(.*?)</p>", "\n$1\n", md)
    md = regex("(?is)<blockquote[^>]*>(.*?)</blockquote>", "\n> $1\n", md)

    // 6. Block containers → newline so adjacent sections don't run together.
    let tableRegex = try! NSRegularExpression(pattern: "(?is)<table\\b[^>]*>(.*?)</table>")
    let rowRegex = try! NSRegularExpression(pattern: "(?is)<tr\\b[^>]*>(.*?)</tr>")
    let cellRegex = try! NSRegularExpression(pattern: "(?is)<t[hd]\\b[^>]*>(.*?)</t[hd]>")
    let tables = tableRegex.matches(in: md, range: NSRange(md.startIndex..., in: md))
    for table in tables.reversed() {
        let body = (md as NSString).substring(with: table.range(at: 1))
        var rows = rowRegex.matches(in: body, range: NSRange(body.startIndex..., in: body)).map { row in
            let content = (body as NSString).substring(with: row.range(at: 1))
            return cellRegex.matches(in: content, range: NSRange(content.startIndex..., in: content)).map { cell in
                regex("\\s+", " ", regex("<[^>]+>", "", (content as NSString).substring(with: cell.range(at: 1))))
                    .trimmingCharacters(in: .whitespacesAndNewlines).replacingOccurrences(of: "|", with: "\\|")
            }
        }
        let count = rows.map(\.count).max() ?? 0
        guard count > 0 else { continue }
        func render(_ row: [String]) -> String { "| " + (0..<count).map { $0 < row.count ? row[$0] : "" }.joined(separator: " | ") + " |" }
        let header = body.range(of: "<th\\b", options: [.regularExpression, .caseInsensitive]) != nil
            ? rows.removeFirst() : Array(repeating: "", count: count)
        let replacement = "\n" + render(header) + "\n" + render(Array(repeating: "---", count: count)) + "\n" + rows.map(render).joined(separator: "\n") + "\n"
        if let range = Range(table.range, in: md) { md.replaceSubrange(range, with: replacement) }
    }
    md = regex("(?i)<(/?)(div|section|ul|ol|table|thead|tbody|tr)[^>]*>", "\n", md)

    // 7. Strip any remaining tags.
    md = regex("(?s)<[^>]+>", "", md)

    // 8. Decode entities.
    md = md
        .replacingOccurrences(of: "&amp;", with: "&")
        .replacingOccurrences(of: "&lt;", with: "<")
        .replacingOccurrences(of: "&gt;", with: ">")
        .replacingOccurrences(of: "&nbsp;", with: " ")
        .replacingOccurrences(of: "&quot;", with: "\"")
        .replacingOccurrences(of: "&#39;", with: "'")

    // 9. Trim each line, collapse blank runs.
    md = md.components(separatedBy: "\n")
        .map { $0.trimmingCharacters(in: .whitespaces) }
        .joined(separator: "\n")
    md = regex("\n{3,}", "\n\n", md)
    return md.trimmingCharacters(in: .whitespacesAndNewlines)
}

/// Render the simple Markdown written to Obsidian back into editable notule HTML.
/// Escaping happens before formatting so external HTML cannot execute in WKWebView.
func markdownToNotuleHTML(_ markdown: String) -> String {
    let content = markdown.replacingOccurrences(of: "(?s)^---\\r?\\n.*?\\r?\\n---\\r?\\n", with: "", options: .regularExpression)
    var output: [String] = []
    var inList = false
    for raw in content.components(separatedBy: .newlines) {
        let line = raw.trimmingCharacters(in: .whitespaces)
        if line.isEmpty {
            if inList { output.append("</ul>"); inList = false }
            continue
        }
        var safe = line.replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
        safe = safe.replacingOccurrences(of: "\\*\\*(.+?)\\*\\*", with: "<strong>$1</strong>", options: .regularExpression)
        safe = safe.replacingOccurrences(of: "(?<!\\*)\\*([^*]+)\\*(?!\\*)", with: "<em>$1</em>", options: .regularExpression)
        if safe.hasPrefix("- ") || safe.hasPrefix("* ") {
            if !inList { output.append("<ul>"); inList = true }
            output.append("<li>\(safe.dropFirst(2))</li>")
        } else {
            if inList { output.append("</ul>"); inList = false }
            let headingLevel = safe.prefix { $0 == "#" }.count
            if (1...4).contains(headingLevel), safe.dropFirst(headingLevel).hasPrefix(" ") {
                output.append("<h\(headingLevel)>\(safe.dropFirst(headingLevel + 1))</h\(headingLevel)>")
            } else if safe.hasPrefix("&gt; ") {
                output.append("<blockquote>\(safe.dropFirst(5))</blockquote>")
            } else {
                output.append("<p>\(safe)</p>")
            }
        }
    }
    if inList { output.append("</ul>") }
    return output.joined(separator: "\n")
}
